// Cleans each row: maps column-name variants, fixes name casing, repairs and
// validates emails, derives the company domain and classifies the address
// (business / free-mail / disposable / role). Unknown columns are kept as-is.
const s = $('Cleaner settings').first().json;
const rows = $input.all().filter((r) => r.json && Object.keys(r.json).length > 0);
if (rows.length === 0) {
 throw new Error('No lead rows found for source "' + s.source + '". Check the file path or sheet name and that the first row holds the column headers.');
}

const FREE = new Set(('gmail.com googlemail.com yahoo.com yahoo.co.uk yahoo.fr yahoo.de ymail.com rocketmail.com hotmail.com hotmail.co.uk hotmail.fr hotmail.de ' +
 'outlook.com outlook.de live.com live.co.uk msn.com windowslive.com aol.com icloud.com me.com mac.com proton.me protonmail.com pm.me ' +
 'gmx.com gmx.de gmx.net gmx.at web.de t-online.de freenet.de mail.com email.com zoho.com zohomail.com yandex.com yandex.ru mail.ru ' +
 'inbox.ru list.ru bk.ru qq.com 163.com 126.com sina.com naver.com daum.net hanmail.net orange.fr wanadoo.fr free.fr laposte.net ' +
 'libero.it virgilio.it tiscali.it alice.it seznam.cz wp.pl o2.pl interia.pl rediffmail.com fastmail.com tutanota.com tuta.io hey.com ' +
 'btinternet.com sky.com comcast.net verizon.net att.net sbcglobal.net cox.net bellsouth.net shaw.ca rogers.com bigpond.com optusnet.com.au ' +
 'uol.com.br bol.com.br terra.com.br').split(/\s+/));
String(s.extra_free_mail_domains || '').split(/[,\s]+/).map((d) => d.trim().toLowerCase()).filter(Boolean).forEach((d) => FREE.add(d));
const DISPOSABLE = new Set(('mailinator.com guerrillamail.com guerrillamail.net sharklasers.com 10minutemail.com 10minutemail.net tempmail.com temp-mail.org ' +
 'tempmail.net throwawaymail.com yopmail.com yopmail.fr trashmail.com getnada.com nada.email dispostable.com maildrop.cc mintemail.com ' +
 'mohmal.com emailondeck.com fakeinbox.com spamgourmet.com mailnesia.com tempr.email discard.email burnermail.io moakt.com ' +
 'mailcatch.com inboxkitten.com tempinbox.com').split(/\s+/));
const ROLE = new Set(('info sales support contact hello hi admin office team marketing billing accounts accounting finance hr jobs careers ' +
 'press media help service enquiries inquiries noreply no-reply webmaster postmaster abuse legal privacy partners orders bookings').split(/\s+/));
const TYPO = {
 'gmial.com': 'gmail.com', 'gmai.com': 'gmail.com', 'gamil.com': 'gmail.com', 'gnail.com': 'gmail.com', 'gmail.co': 'gmail.com', 'gmail.con': 'gmail.com', 'gmaill.com': 'gmail.com',
 'hotmial.com': 'hotmail.com', 'hotmai.com': 'hotmail.com', 'hotmail.co': 'hotmail.com', 'hotmail.con': 'hotmail.com',
 'yahooo.com': 'yahoo.com', 'yaho.com': 'yahoo.com', 'yahoo.co': 'yahoo.com', 'yahoo.con': 'yahoo.com',
 'outlok.com': 'outlook.com', 'outloo.com': 'outlook.com', 'outlook.co': 'outlook.com', 'outlook.con': 'outlook.com',
 'iclould.com': 'icloud.com', 'icloud.co': 'icloud.com', 'iclod.com': 'icloud.com',
};
const PARTICLES = new Set(['van', 'von', 'der', 'den', 'de', 'del', 'della', 'di', 'da', 'du', 'dos', 'das', 'la', 'le', 'bin', 'al', 'ter', 'ten']);
const HONORIFICS = /^(mr|mrs|ms|miss|mx|dr|prof|sir|madam)\.?\s+/i;

const ALIASES = {
 first_name: ['first_name', 'firstname', 'first', 'given_name', 'givenname', 'vorname', 'prenom'],
 last_name: ['last_name', 'lastname', 'last', 'surname', 'family_name', 'familyname', 'nachname', 'nom'],
 full_name: ['full_name', 'fullname', 'name', 'contact', 'contact_name', 'lead_name', 'person'],
 email: ['email', 'e_mail', 'email_address', 'emailaddress', 'work_email', 'business_email', 'mail'],
 company: ['company', 'company_name', 'organization', 'organisation', 'account', 'account_name', 'business', 'firma'],
 website: ['website', 'web', 'url', 'domain', 'company_website', 'company_url', 'site', 'homepage'],
};
const keyOf = (k) => String(k).trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');

function smartCase(str) {
 const t = String(str || '').replace(/\s+/g, ' ').trim();
 if (!t) return '';
 // Keep names that already have deliberate mixed case (e.g. "DeShawn", "McKenzie").
 const mixed = t !== t.toLowerCase() && t !== t.toUpperCase();
 if (mixed && !/^[A-Z][a-z]+(\s[a-z]+)*$/.test(t)) return t;
 return t.toLowerCase().split(' ').map((w, idx) => {
 if (idx > 0 && PARTICLES.has(w)) return w;
 return w.split('-').map((p) => {
 if (!p) return p;
 let out = p.charAt(0).toUpperCase() + p.slice(1);
 out = out.replace(/^(O|D)'(\p{L})/u, (m, a, b) => a + "'" + b.toUpperCase());
 out = out.replace(/^Mc(\p{L})/u, (m, a) => 'Mc' + a.toUpperCase());
 return out;
 }).join('-');
 }).join(' ');
}

function splitFull(full) {
 const parts = full.split(' ').filter(Boolean);
 if (parts.length < 2) return { first: parts[0] || '', last: '' };
 let i = parts.length - 1;
 while (i > 1 && PARTICLES.has(parts[i - 1].toLowerCase())) i--; // "van der Berg" stays together
 return { first: parts.slice(0, i).join(' '), last: parts.slice(i).join(' ') };
}

function cleanDomain(v) {
 let d = String(v || '').trim().toLowerCase();
 if (!d) return '';
 d = d.replace(/^[a-z]+:\/\//, '').replace(/^www\d?\./, '').split(/[\/?#]/)[0].split(':')[0].replace(/\.$/, '');
 return /^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(d) ? d : '';
}

const EMAIL_RE = /^[a-z0-9.!#$%&'*+\/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)*\.[a-z]{2,}$/;

return rows.map((row, index) => {
 const src = row.json;
 const picked = {};
 const extra = {};
 for (const [k, v] of Object.entries(src)) {
 const nk = keyOf(k);
 const field = Object.keys(ALIASES).find((f) => ALIASES[f].includes(nk));
 if (field && picked[field] === undefined) picked[field] = v == null ? '' : String(v);
 else if (nk !== 'row_number') extra[k] = v;
 }
 const issues = [];
 const fixes = [];

 // Names
 let full = String(picked.full_name || '').replace(HONORIFICS, '');
 let first = smartCase(String(picked.first_name || '').replace(HONORIFICS, ''));
 let last = smartCase(picked.last_name);
 if (!first && !last && full) { const sp = splitFull(smartCase(full)); first = sp.first; last = sp.last; }
 const fullName = [first, last].filter(Boolean).join(' ') || smartCase(full);
 if (!fullName) issues.push('missing name');

 // Email
 const rawEmail = String(picked.email || '');
 let email = rawEmail.trim().toLowerCase().replace(/^mailto:/, '').replace(/^<|>$/g, '').replace(/[;,.]+$/, '').replace(/\s+/g, '');
 let emailStatus = 'missing';
 if (email) {
 const at = email.lastIndexOf('@');
 let dom = at > 0 ? email.slice(at + 1) : '';
 if (s.fix_email_typos !== false) {
 let fixed = TYPO[dom] || dom.replace(/\.(con|cmo|ocm|comm|vom)$/, '.com');
 if (fixed !== dom) { fixes.push('email domain ' + dom + ' -> ' + fixed); email = email.slice(0, at + 1) + fixed; dom = fixed; }
 }
 emailStatus = EMAIL_RE.test(email) ? 'valid' : 'invalid';
 }
 if (emailStatus === 'missing') issues.push('missing email');
 if (emailStatus === 'invalid') issues.push('invalid email syntax');

 const emailDomain = emailStatus === 'valid' ? email.split('@')[1] : '';
 const local = emailStatus === 'valid' ? email.split('@')[0] : '';
 let emailType = '';
 if (emailStatus === 'valid') {
 if (DISPOSABLE.has(emailDomain)) emailType = 'disposable';
 else if (FREE.has(emailDomain)) emailType = 'free';
 else if (ROLE.has(local.split('+')[0])) emailType = 'role';
 else emailType = 'business';
 }
 if (emailType === 'disposable') issues.push('disposable email domain');

 // Company + domain
 const company = String(picked.company || '').replace(/\s+/g, ' ').trim();
 const companyClean = company && company === company.toUpperCase() && company.length > 4 ? smartCase(company) : company;
 const webDomain = cleanDomain(picked.website);
 if (picked.website && !webDomain) issues.push('website not a valid domain');
 let companyDomain = webDomain;
 let domainSource = webDomain ? 'website' : '';
 if (!companyDomain && (emailType === 'business' || emailType === 'role')) { companyDomain = emailDomain; domainSource = 'email'; }

 // Canonical email for duplicate matching: lowercase, drop +tags, ignore dots for Gmail.
 let emailKey = '';
 if (emailStatus === 'valid') {
 let [l, d] = email.split('@');
 l = l.split('+')[0];
 if (d === 'googlemail.com') d = 'gmail.com';
 if (d === 'gmail.com') l = l.replace(/\./g, '');
 emailKey = l + '@' + d;
 }
 const companyKey = companyClean.toLowerCase()
 .replace(/[.,]/g, ' ')
 .replace(/\b(inc|llc|ltd|limited|gmbh|ag|bv|sarl|sas|srl|spa|plc|corp|corporation|co|company|pty|oy|ab|as)\b/g, '')
 .replace(/[^a-z0-9\u00c0-\u024f]+/g, ' ').trim();

 return {
 json: Object.assign({
 source_row: src.row_number || index + 2, // +2 = header row + 1-based
 first_name: first,
 last_name: last,
 full_name: fullName,
 email,
 email_status: emailStatus,
 email_type: emailType,
 is_free_mail: emailType === 'free',
 company: companyClean,
 company_domain: companyDomain,
 domain_source: domainSource,
 fixes: fixes.join('; '),
 issues: issues.join('; '),
 _email_key: emailKey,
 _name_key: fullName.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z]+/g, ' ').trim(),
 _company_key: companyKey,
 }, extra),
 pairedItem: row.pairedItem || { item: index },
 };
});

// Groups rows that are the same person and merges them into one row:
// match on canonical email first, then on name + company domain, then name + company.
// The first row wins; empty fields are filled from its duplicates.
const items = $input.all().map((x) => x.json);
const parent = items.map((_, i) => i);
const find = (i) => (parent[i] === i ? i : (parent[i] = find(parent[i])));
const union = (a, b) => { const ra = find(a), rb = find(b); if (ra !== rb) parent[Math.max(ra, rb)] = Math.min(ra, rb); };

const index = {};
items.forEach((r, i) => {
 const keys = [];
 if (r._email_key) keys.push('e:' + r._email_key);
 if (r._name_key && r.company_domain) keys.push('nd:' + r._name_key + '|' + r.company_domain);
 if (r._name_key && r._company_key) keys.push('nc:' + r._name_key + '|' + r._company_key);
 keys.forEach((k) => { if (index[k] !== undefined) union(index[k], i); else index[k] = i; });
});

const groups = new Map();
items.forEach((r, i) => { const g = find(i); if (!groups.has(g)) groups.set(g, []); groups.get(g).push(i); });

const out = [];
for (const [g, members] of groups) {
 const merged = Object.assign({}, items[members[0]]);
 // Two different valid emails for one person: keep the business one as primary.
 // Addresses that only differ by +tag, case or Gmail dots are one mailbox, so list each mailbox once.
 const byKey = new Map();
 members.forEach((i) => { const r = items[i]; if (r.email_status === 'valid' && !byKey.has(r._email_key)) byKey.set(r._email_key, r.email); });
 const emails = [...byKey.values()];
 if (emails.length > 1) {
 const best = members.map((i) => items[i]).find((r) => r.email_type === 'business') || merged;
 ['email', 'email_status', 'email_type', 'is_free_mail'].forEach((k) => { merged[k] = best[k]; });
 }
 for (const i of members.slice(1)) {
 for (const [k, v] of Object.entries(items[i])) {
 if ((merged[k] === '' || merged[k] === undefined || merged[k] === null) && v !== '' && v != null) merged[k] = v;
 }
 }
 const issues = [...new Set(String(merged.issues || '').split('; ').filter(Boolean))];
 // An issue is resolved if the merged row now has the value.
 const still = issues.filter((x) => !(x === 'missing email' && merged.email_status === 'valid') && !(x === 'missing name' && merged.full_name));
 merged.issues = still.join('; ');
 merged.duplicates_merged = members.length - 1;
 merged.merged_rows = members.length > 1 ? members.map((i) => items[i].source_row).join(', ') : '';
 merged.other_emails = [...byKey].filter(([k]) => k !== merged._email_key).map(([, e]) => e).join(', ');
 merged.lead_status = merged.email_status === 'valid' && merged.email_type !== 'disposable' && merged.full_name ? 'ready' : 'review';
 merged.dedupe_key = merged._email_key || ('name:' + merged._name_key + '|' + (merged.company_domain || merged._company_key));
 delete merged._email_key; delete merged._name_key; delete merged._company_key;
 out.push({ json: merged, pairedItem: members.map((i) => ({ item: i })) });
}
return out;

// One summary item so you can see at a glance what the run changed.
const rows = $input.all().map((x) => x.json);
const inputRows = $('Normalize and validate leads').all().length;
const count = (f) => rows.filter(f).length;
return [{
 json: {
 input_rows: inputRows,
 output_rows: rows.length,
 duplicates_merged: inputRows - rows.length,
 ready: count((r) => r.lead_status === 'ready'),
 needs_review: count((r) => r.lead_status === 'review'),
 business_emails: count((r) => r.email_type === 'business'),
 free_mail: count((r) => r.email_type === 'free'),
 role_addresses: count((r) => r.email_type === 'role'),
 disposable: count((r) => r.email_type === 'disposable'),
 invalid_or_missing_email: count((r) => r.email_status !== 'valid'),
 emails_auto_fixed: count((r) => /email domain/.test(r.fixes || '')),
 },
}];
